public static int countFit(double[] heights) {
    int count = 0;
    int i = 0;
    while (heights[i] != 0) {
        if (heights[i] >= 1.75) {
            count++;
        }
        i++;
    }
    return count;
}

public static double tallest(double[] heights) {
    double max = heights[0];
    int i = 1;
    while (heights[i] != 0) {
        if (heights[i] > max) {
            max = heights[i];
        }
        i++;
    }
    return max;
}

public static int tallestPosition(double[] heights) {
    int best = 0;   // המקום במערך של הגבוה ביותר עד עכשיו
    int i = 1;
    while (heights[i] != 0) {
        if (heights[i] > heights[best]) {
            best = i;
        }
        i++;
    }
    return best + 1;   // ביומן מתחילים ב-1
}

